func testGetUsers() {
  PassingTestsExample.mockService
    .uponReceiving("A request for a list of users")
    .given(ProviderState(description: "users exist", params: ["first_name": "John"]))
    .withRequest(method: .GET, path: "/api/users")
    .willRespondWith(status: 200, headers: nil,
                     body: ["data": Matcher.EachLike(["first_name": Matcher.SomethingLike("John")])])
    .run(timeout: 1) { url, done in
      RestManager(baseUrl: url).getUsers { users in
        XCTAssertEqual(users.first?.firstName, "John"); done()   // always call done()
      }
    }
}
